"""Restaurant & Cloud Kitchen toolkit (kit id: restaurant). Text for the kit page, the item pages and the "How to use" sheets."""

KITS = [
    dict(id='restaurant', name='Restaurant & Cloud Kitchen', icon='🍽️', color='#DC2626',
         title='Restaurant & Cloud Kitchen Toolkit: Sales Register, Recipe Costing, Stock and Roster',
         desc='Free Excel templates for restaurants, dhabas and cloud kitchens: daily sales by payment mode, recipe cost sheet, kitchen stock and wastage, staff roster, hygiene checklist and an online bill/KOT maker.',
         intro=['A restaurant owner closes every night with the same questions: how much did we sell in cash, UPI, card, Swiggy and Zomato, does the drawer match, what does each dish really cost us, what got thrown away, and who is on shift tomorrow. Most small restaurants and cloud kitchens answer them on scraps of paper or not at all.',
                'This toolkit turns those nightly jobs into ready Excel workbooks: a sales register that splits takings by payment mode and checks the cash drawer, a recipe cost sheet that shows the food cost percent and margin of every dish, a kitchen stock and wastage register, a weekly staff roster that counts hours, and a printable hygiene checklist and temperature log. The online bill maker prints a GST restaurant bill or a kitchen order ticket (KOT) from a phone.'],
         who='Restaurant and dhaba owners, cloud kitchens and home kitchens selling on Swiggy and Zomato, cafés, canteens, caterers, restaurant managers and head chefs.'),
]

ITEMS = [
    dict(id='rest-daily-sales-excel', kit='restaurant', kind='excel', icon='💵', name='Restaurant Daily Sales & Cash Register (Excel)',
         title='Restaurant Daily Sales Register in Excel: Cash, UPI, Card, Swiggy and Zomato',
         desc='Free Excel daily sales register for restaurants and cloud kitchens: sales by payment mode, cash drawer check with short or excess, aggregator commission and a month summary.',
         files=[('Restaurant-Daily-Sales-Register.xlsx', 'Daily sales and cash register workbook')],
         preview={'Restaurant-Daily-Sales-Register.xlsx': ('Daily Sales', 'A4:Q10')},
         lead='One row per day for the whole month. Type the day\'s takings under Cash, UPI, Card, Swiggy, Zomato and Other, the cash you paid out of the counter and the cash you banked. The register adds up the day, works out the average bill, tells you how much cash should be in the drawer, and shows the shortage or excess once you type the counted cash. The Month Summary splits sales by payment mode, estimates aggregator commission and the money still to arrive in the bank.',
         inside=['Settings: restaurant name, month, opening cash float and a payment-mode table with an editable commission percent for Swiggy, Zomato, card or any other mode',
                 'Daily Sales sheet: dates of the month fill in by themselves; number of bills, sales by six payment modes, total, average bill value',
                 'Cash drawer check for every day: opening cash, cash paid out, cash deposited, expected cash, counted cash and short / excess (red when short)',
                 'Month Summary: sales and share by payment mode, estimated commission plus GST on commission, net amount to be received, best day, average daily sales and total cash difference',
                 'A bar chart of sales by payment mode for your monthly review'],
         steps=['Open the Settings sheet. Type your restaurant name, the first day of the month (for example 01-11-2026) and the cash float you keep in the drawer at opening.',
                'In the payment-mode table, type the commission percent you pay on Swiggy and Zomato orders (and card charges if you want them counted). Leave Cash and UPI at 0.',
                'Every night, on the Daily Sales sheet, type the number of bills and the sales in each payment mode from your billing software or KOT book.',
                'Type cash paid out of the counter (vegetables, gas, staff advance) and cash you deposited in the bank or handed to the owner.',
                'Count the drawer and type the counted cash. Short / Excess shows the difference; investigate anything in red the same night.',
                'At month end, open the Month Summary for totals by mode and the commission estimate, then start a fresh copy for the next month.'],
         tips=['Use the sales figure after discount and before GST if you want the register to match your GST returns; use the figure including GST if you want it to match the money received. Pick one and stick to it.',
                'Aggregator payouts deduct commission, payment gateway fees, GST on those charges, TCS and TDS, and sometimes ad spend; the estimate here covers commission and GST on it only. Match each weekly payout with the statement from Swiggy or Zomato.',
                'Each day starts from the cash you counted the night before, so a shortage shows only on the day it happened instead of hiding in later days.',
                'Average bill value (sales ÷ bills) is one of the best numbers to watch: a combo or an add-on suggestion moves it more than a new dish.'],
         faqs=[('Where does each day\'s opening cash come from?', 'The first day uses the float on the Settings sheet. After that, each day starts with the cash you counted the night before; if you left the counted cell empty, it starts with the expected cash instead.'),
               ('How is Swiggy or Zomato commission worked out?', 'Sales in that mode multiplied by the commission percent you typed, plus GST on the commission (18 percent by default, editable). Real payouts also deduct gateway fees, TCS, TDS and promotions, so treat this as an estimate.'),
               ('Can I add another payment mode like Paytm or a food-court card?', 'Rename the "Other" mode on the Settings sheet; the column heading and the summary follow the new name.'),
               ('Does it work for a cloud kitchen with no dine-in?', 'Yes. Leave Cash and Card empty if you do not use them; the Swiggy, Zomato and Other columns and the commission summary are what matter for a delivery-only kitchen.')]),

    dict(id='rest-recipe-costing-excel', kit='restaurant', kind='excel', icon='🧮', name='Recipe Cost Sheet & Menu Pricing (Excel)',
         title='Recipe Costing Template in Excel: Food Cost Percent, Plate Cost and Menu Price',
         desc='Free Excel recipe cost sheet for restaurants: ingredient prices with yield, recipe lines, cost per portion, food cost percent, gross margin and a suggested menu price.',
         files=[('Restaurant-Recipe-Costing.xlsx', 'Recipe costing and menu pricing workbook')],
         preview={'Restaurant-Recipe-Costing.xlsx': ('Menu Costing', 'A6:L12')},
         lead='Know what every plate really costs. List your ingredients once with their purchase price and usable yield (what is left after peeling, cleaning or trimming). Write each recipe as a few lines of ingredient and quantity. The Menu Costing sheet then shows the cost per portion of every dish, its food cost percent at your menu price, the gross margin in rupees and the price you would need to hit your target food cost.',
         inside=['Ingredients sheet: ingredient, purchase unit, price per unit, usable yield percent and the true cost per usable unit',
                 'Recipes sheet: 600 ready lines; pick a dish and an ingredient, type the quantity, and the line cost fills in',
                 'Menu Costing sheet: portions per recipe, extra cost per plate (gas, garnish, packaging), cost per portion, menu price, price with GST, food cost percent, margin and a suggested price at your target food cost',
                 'Dishes above the target food cost turn red so you know which prices or recipes to look at',
                 'Sample data for six popular North Indian dishes so you can see how it works before typing your own'],
         steps=['On the Ingredients sheet replace the samples with your ingredients. Type the price for one purchase unit (per kg, per litre, per piece) and the usable yield percent (100 if nothing is thrown away).',
                'On the Menu Costing sheet type each dish name, its category, how many portions one batch of the recipe makes, any extra cost per plate and the menu price before GST.',
                'On the Recipes sheet add one line per ingredient of each dish: pick the dish, pick the ingredient and type the quantity used for the whole batch in the same unit as the purchase unit (write 150 g as 0.15 kg).',
                'Back on Menu Costing, read the cost per portion, food cost percent and margin. Change the target food cost percent at the top if yours is different from 30 percent.',
                'Every time a supplier changes a price, update the Ingredients sheet; every dish that uses it recalculates.'],
         tips=['Weigh a real batch once instead of guessing: portion size drives food cost more than the price of any one ingredient.',
               'Yield matters: if 1 kg of onion gives 0.9 kg after peeling, a yield of 90 percent raises its true cost by about 11 percent.',
               'Many Indian restaurants aim for a food cost of 28 to 35 percent; a cloud kitchen paying aggregator commission often needs a lower food cost to stay profitable.',
               'Add the cost of the container, lid and carry bag as "extra per plate" for delivery dishes, or keep separate dine-in and delivery rows for the same dish.'],
         faqs=[('What is food cost percent?', 'The cost of the ingredients in one portion divided by the menu price of that portion. A dish that costs ₹84 to make and sells for ₹320 has a food cost of about 26 percent.'),
               ('How is the suggested price worked out?', 'Cost per portion divided by your target food cost percent, rounded up to the next ₹5. It is a starting point; your competitors, your portion size and what guests expect still decide the final price.'),
               ('Should the menu price include GST?', 'Type the price before GST. The sheet also shows the price with GST at the rate on the Menu Costing sheet (5 percent for most restaurants) so you can print either on your menu.'),
               ('Can one recipe use another recipe, like a gravy base?', 'Cost the base as its own dish, then add it to the Ingredients sheet with its cost per kg and use it like any other ingredient.')]),

    dict(id='rest-stock-wastage-excel', kit='restaurant', kind='excel', icon='🥬', name='Kitchen Stock & Wastage Register (Excel)',
         title='Kitchen Stock Register and Food Wastage Log in Excel for Restaurants',
         desc='Free Excel kitchen inventory and wastage register: purchases, issues to kitchen, wastage with reasons, staff meals, closing stock, par level alerts and a wastage report by reason.',
         files=[('Restaurant-Kitchen-Stock-Wastage.xlsx', 'Kitchen stock and wastage workbook')],
         preview={'Restaurant-Kitchen-Stock-Wastage.xlsx': ('Stock', 'A4:L14')},
         lead='Every rupee of food that is bought, used, eaten by staff or thrown away is written in one simple list. The workbook keeps the closing stock and value of every item, flags items that have fallen below the par level, compares the book stock with your physical count, and turns the wastage entries into a report by reason and by item for any period you choose.',
         inside=['Items sheet: item, category, unit, storage (chiller, freezer, dry store), opening stock, par level and rate',
                 'Entries sheet with 1,500 rows: date, item, type (purchase, issue to kitchen, wastage, staff meal, return to supplier), quantity, wastage reason and who recorded it; unit and value fill in',
                 'Stock sheet: opening, purchased, issued, wasted, staff meals, returned, closing stock and value, a red "Order now" flag below par, and a physical count column with variance',
                 'Wastage Report: pick from and to dates; wastage value by reason, wastage as a percent of purchases, and wastage value by item',
                 'Ready lists of common wastage reasons: spoiled or expired, over-production, cooking error, dropped or spilled, customer return, trim and peel'],
         steps=['On the Items sheet replace the samples with your items. Type the opening stock you have today, a par level (the least you want to hold) and the purchase rate per unit.',
                'Each time stock moves, add a row on the Entries sheet: date, item, type and quantity. Use the same unit as on the Items sheet.',
                'For wastage, also pick the reason and type who recorded it. Ask the kitchen to write waste on a sheet near the bin and enter it at day end.',
                'Open the Stock sheet to see closing stock and value. Items at or below par show "Order now".',
                'Once a week, count the store and type the counted quantity in the Count column. The variance shows stock that went missing without an entry.',
                'On the Wastage Report type the from and to dates to see what was wasted, why and how much it cost.'],
         tips=['Write wastage at cost price, every day, without blame: the point is to see the pattern (for example over-production on Mondays), not to punish the cook.',
               'Issue to the kitchen from the store once or twice a day against a written requisition; it makes the variance meaningful.',
               'Follow first in, first out (FIFO): put new stock behind old stock and label containers with the date received.',
               'A wastage figure above 4 to 5 percent of purchases usually means ordering or prep quantities need a second look.'],
         faqs=[('What is the difference between "issue to kitchen" and "wastage"?', 'Issue is stock that leaves the store to be cooked and sold. Wastage is stock (raw or cooked) that is thrown away. Both reduce stock, but only wastage appears in the wastage report.'),
               ('Why do staff meals have their own type?', 'Food given to staff is a real cost but it is not waste. Keeping it separate stops it from hiding inside wastage or inside variance.'),
               ('What does variance mean?', 'Counted quantity minus the stock the register expects. A minus figure means stock is missing without an entry: unrecorded waste, over-portioning or theft.'),
               ('Can I track cooked food waste too?', 'Yes. Add the dish as an item with unit "portion" and its cost per portion from the recipe cost sheet, then log leftover or returned portions as wastage.')]),

    dict(id='rest-shift-roster-excel', kit='restaurant', kind='excel', icon='🗓️', name='Restaurant Staff Shift Roster (Excel)',
         title='Restaurant Staff Rota in Excel: Weekly Shift Roster with Hours and Cover Count',
         desc='Free Excel weekly shift roster for restaurant staff: shift codes with times, split shifts, hours per person, weekly off check and how many people are on duty in each shift.',
         files=[('Restaurant-Staff-Shift-Roster.xlsx', 'Staff shift roster workbook')],
         preview={'Restaurant-Staff-Shift-Roster.xlsx': ('Roster', 'A5:M15')},
         lead='Plan the week for your kitchen and floor team on one page you can print and pin up. Set up your shifts once (morning, evening, general, split, closing) with their times and breaks, list your staff with their roles, and fill the week with shift codes from a drop-down. The roster counts each person\'s hours, warns when someone has no weekly off or is over their hour limit, and shows how many people are on duty in each shift and each role every day.',
         inside=['Shifts sheet: code, name, start and end time, an optional second part for split shifts, unpaid break and paid hours worked out automatically, including shifts that end after midnight',
                 'Staff sheet: name, role (chef, cook, helper, steward, captain, cashier, dishwasher, delivery rider, manager), phone and weekly hour limit',
                 'Roster sheet for a week: dates fill in from the week start, shift code drop-down for every person and day, hours, days worked, weekly offs and a check column',
                 'Coverage sheet: people on duty per shift and per role for each day, so you can see a short Saturday dinner before it happens',
                 'Landscape A4 print layout with a shift-time legend'],
         steps=['On the Shifts sheet check the sample shifts and change the times to match your restaurant. Keep OFF (weekly off) and L (leave) as they are.',
                'On the Staff sheet list everyone with their role and weekly hour limit (48 is a common limit; check your state\'s shops and establishments rules).',
                'On the Roster sheet type the first day of the week (for example a Monday) in the yellow cell.',
                'Pick a shift code for every person on every day. Hours, days worked and offs calculate as you go.',
                'Check the Check column for "No weekly off" or "Over hours", and look at the Coverage sheet for days with too few people in a role.',
                'Print the Roster sheet (it fits A4 landscape) and pin it up, or share it as a PDF on the staff WhatsApp group. Save a copy for each week.'],
         tips=['Plan the busiest shifts first (Friday and Saturday dinner, Sunday lunch) and fit weekly offs around them.',
               'Rotate weekly offs fairly; nobody should always lose their weekend.',
               'A split shift (lunch and dinner with a gap) suits small restaurants, but make sure the gap is real rest.',
               'Keep at least one person with food safety training on every shift.'],
         faqs=[('How are hours worked out for shifts after midnight?', 'If the end time is earlier than the start time, the shift is taken to end the next day, so 17:00 to 01:00 counts as 8 hours before the break is taken off.'),
               ('Can I add more shifts?', 'Yes. Add a row on the Shifts sheet with a new short code; it appears in the roster drop-down and on the Coverage sheet.'),
               ('Does it check labour law?', 'It only flags a missing weekly off and hours above the limit you type for each person. Working hours, overtime pay and rest rules depend on your state; check them with your consultant.'),
               ('How many staff can I schedule?', 'Up to 60 people on one roster. For a bigger team, keep a copy per outlet or per department.')]),

    dict(id='rest-hygiene-checklist-word', kit='restaurant', kind='word', icon='🧼', name='Kitchen Hygiene Checklist & Temperature Log (Word)',
         title='Restaurant Kitchen Hygiene Checklist and Fridge Temperature Log (FSSAI-style)',
         desc='Free printable kitchen hygiene checklist for restaurants in Word, based on common FSSAI good hygiene practices, with a weekly tick sheet, monthly checks and a temperature log.',
         files=[('Restaurant-Kitchen-Hygiene-Checklist.docx', 'Hygiene checklist (Word)'), ('Restaurant-Temperature-Log.docx', 'Temperature log (Word)')],
         lead='Two printable sheets for the kitchen wall. The hygiene checklist lists the daily opening, service and closing checks a well-run kitchen does, with a tick box for every day of the week, plus weekly and monthly checks and a corrective-action box. The temperature log records fridge, freezer, cooking and hot-holding temperatures twice a day for a month. Both follow common good hygiene practices that FSSAI expects from food businesses, written in plain English.',
         inside=['Daily checklist with Monday to Sunday columns: personal hygiene, raw material receiving, storage, cooking, service and closing clean-down',
                 'Weekly and monthly checks: deep cleaning, pest control visits, exhaust and grease trap, water tank, medical fitness of food handlers, trained supervisor, licence display',
                 'Corrective action table: what was wrong, what was done, by whom',
                 'Temperature log for up to four fridges or freezers, cooking core temperature and hot holding, morning and evening, for 31 days',
                 'Target temperatures printed on the sheet: chilled at 5 °C or below, frozen at −18 °C or below, cooked to 75 °C in the centre, hot food held above 60 °C'],
         steps=['Download both files and open them in Word, Google Docs or LibreOffice.',
                'Type your restaurant name and FSSAI licence or registration number at the top. Remove any check that does not apply to your kitchen and add your own.',
                'Print one checklist per week and one temperature log per month. Pin them near the kitchen entry and the fridges.',
                'The shift supervisor ticks each check at the time it is done and initials the day. A cross means "not done": write what was done about it in the corrective action table.',
                'Read fridge and freezer thermometers at opening and before closing and write the temperature, not just a tick.',
                'File the completed sheets month by month; they show a food safety officer or a customer that hygiene is checked every day.'],
         tips=['Put a probe thermometer in the kitchen and a simple dial thermometer inside every fridge; you cannot log what you cannot measure.',
               'Train new staff on the checklist in their first week; it doubles as a hygiene induction.',
               'This is a working checklist, not an official FSSAI form. Your licence conditions and the latest FSSAI rules decide what you must do and record.'],
         faqs=[('Is this an official FSSAI format?', 'No. It brings together common points from FSSAI\'s good hygiene and sanitary practices for food businesses (Schedule 4) in a form a busy kitchen can use. Check your licence conditions and the FSSAI website for what applies to you.'),
               ('What temperatures should fridges and freezers show?', 'The usual targets are 5 °C or below for chilled food and −18 °C or below for frozen food. Hot food kept for service should stay above 60 °C, and meat and poultry should reach about 75 °C in the centre when cooked.'),
               ('How long should we keep these records?', 'Keep them at least as long as your food safety officer, auditor or brand standards ask; many kitchens keep a full year.'),
               ('Can I use it for a cloud kitchen or canteen?', 'Yes. The checks are the same; delete the dine-in service lines if you only deliver.')]),

    dict(id='rest-bill-maker', kit='restaurant', kind='online', tool='rest-bill', icon='⚡', name='Online Restaurant Bill & KOT Maker',
         title='Online Restaurant Bill Maker with GST 5%, Service Charge and KOT Printing',
         desc='Make a restaurant bill or a kitchen order ticket (KOT) online: table, covers, dishes, GST 5% or 18% split into CGST and SGST, optional service charge, discount. Print or download.',
         lead='Make a clean restaurant bill or kitchen order ticket from a phone or computer. Type the table, the dishes and quantities; switch to KOT to print the order for the kitchen without prices, then switch back to Bill to total it with discount, an optional service charge, packing charges and GST split into CGST and SGST. The FSSAI licence number prints on the bill. Your restaurant details stay saved on this device; nothing is uploaded.',
         inside=['Bill or KOT (kitchen order ticket) from the same order',
                 'Dine-in, takeaway or delivery, table number, covers and steward name',
                 'GST at 5 percent (most restaurants), 18 percent (restaurants in hotels charging above ₹7,500 a night for a room) or no GST for composition and unregistered businesses',
                 'Optional service charge shown as voluntary, discount percent and packing charges',
                 'Print / Save as PDF, Excel and Word downloads, works offline once installed'],
         steps=['Type your restaurant name, address, phone, GSTIN and FSSAI number once. They stay saved on this device.',
                'Choose KOT, type the table and covers, and add the dishes with quantity and any note for the kitchen (for example "less spicy"). Print it for the kitchen.',
                'When the guest asks for the bill, switch Document to Bill. Add rates if you have not, and any discount or packing charge.',
                'Pick the GST rate that applies to you. Add a service charge only if your policy has one; the bill marks it as voluntary.',
                'Check the totals, choose the payment mode and press Print / PDF, or download Excel or Word.'],
         tips=['On a phone, use Print › Save as PDF and share the bill on WhatsApp.',
               'A 58 mm or 80 mm thermal printer prints the page scaled down; for crisp thermal bills keep the item names short.',
               'Use "New bill (keep my details)" for the next table; the bill number moves to the next one by itself.'],
         faqs=[('Which GST rate should a restaurant charge?', 'Most standalone restaurants, dhabas, cafés and cloud kitchens charge 5 percent GST without input tax credit. Restaurants inside hotels where a room is charged above ₹7,500 a night charge 18 percent with input tax credit. Businesses under the composition scheme or without GST registration cannot charge GST. Confirm your case with your tax adviser.'),
               ('Is service charge compulsory?', 'No. Under the Central Consumer Protection Authority guidelines of July 2022, a restaurant cannot add a service charge automatically or by default, and a guest can ask for it to be removed. This tool leaves it at 0 and labels it as voluntary when you add one. GST applies on a service charge that is collected.'),
               ('Why is the FSSAI number on the bill?', 'FSSAI requires food businesses to show their FSSAI licence or registration number on bills and cash memos.'),
               ('Is my data stored online?', 'No. The bill is made in your browser; only your restaurant details and the last bill number are remembered on this device.')]),
]
